function params(experiment,input={}){const p={...experiment.modelParams};for(const c of experiment.controls||[]){let v=input[c.key]??c.value;if(c.options){if(!c.options.some(o=>o.value===v))v=c.value;}else{v=Number(v);if(!Number.isFinite(v))v=c.value;v=clamp(v,c.min,c.max);}p[c.key]=v;}return p;}
